package got.client.ambient; import got.GOTMod; import net.minecraft.client.model.geom.ModelLayerLocation; import net.minecraft.resources.ResourceLocation; public final class GOTAmbientLayers { public static final ModelLayerLocation BIRD=l("bird_ambient"),BUTTERFLY=l("butterfly"),FLAMINGO=l("flamingo"),SWAN=l("swan"),MIDGES=l("midges"); private static ModelLayerLocation l(String s){return new ModelLayerLocation(new ResourceLocation(GOTMod.MOD_ID,s),"main");} }
